slides.solution:
def fetch_all(fetch):
    first = fetch(1)
    results = list(first["results"])
    for page in range(2, first["total_pages"] + 1):
        results.extend(fetch(page)["results"])
    return results

# A pretend hotel-search API with 3 pages
DATA = {1: ["Taj", "Oberoi"], 2: ["ITC", "Leela"], 3: ["Lemon Tree"]}
