    return {"results": DATA[page], "total_pages": 3}

print(fetch_all(fake_fetch))

slides.tests:
calls = []
def api(page):
    calls.append(page)
    pages = {1: ["a", "b"], 2: ["c", "d"], 3: ["e"]}
    return {"results": pages[page], "total_pages": 3}

got = fetch_all(api)
assert got == ["a", "b", "c", "d", "e"], f"The 3 pages hold a, b, c, d, e. You returned {got}."
assert calls == [1, 2, 3], f"Call fetch once per page, in order: [1, 2, 3]. You called it with {calls}. Every extra call costs money and rate limit."

def single(page):
    return {"results": ["only"], "total_pages": 1}
assert fetch_all(single) == ["only"], "With a single page, return its results."

def empty(page):
    assert page == 1, "When total_pages is 0, there's nothing beyond page 1 to fetch."
    return {"results": [], "total_pages": 0}
assert fetch_all(empty) == [], "No results at all: return an empty list."

