class APIError(Exception):
    pass

RETRYABLE = {429, 500, 502, 503}

def fetch_with_retry(get, url, retries=3):
    for attempt in range(1, retries + 1):
        response = get(url)
        status = response["status"]
        if status == 200:
            return response["body"]
        print(f"attempt {attempt}: got {status}, retrying")
        # real code would wait here: time.sleep(2 ** attempt)
    raise APIError(f"gave up on {url}")

def fake_get(url):              # this user doesn't exist
    return {"status": 404, "body": None}

try:
    fetch_with_retry(fake_get, "/v1/users/999")
except APIError as e:
    print("Error:", e)

slides.solution:
class APIError(Exception):
    pass

RETRYABLE = {429, 500, 502, 503}

def fetch_with_retry(get, url, retries=3):
    for attempt in range(1, retries + 1):
        response = get(url)
        status = response["status"]
        if status == 200:
            return response["body"]
        if status not in RETRYABLE:
            raise APIError(f"{status} for {url}: not worth retrying")
        print(f"attempt {attempt}: got {status}, retrying")
        # real code would wait here: time.sleep(2 ** attempt)
    raise APIError(f"gave up on {url}")

def fake_get(url):              # this user doesn't exist
    return {"status": 404, "body": None}

try:
    fetch_with_retry(fake_get, "/v1/users/999")
except APIError as e:
    print("Error:", e)
